/bin/bash -lc "python3 - <<'PY'
import gzip,csv,heapq,math
p='/workspace/inputs/sample.swap.atac.q2.tsv.gz'
cols=None; top={}; total=None; n=0
with gzip.open(p,'rt') as f:
    r=csv.reader(f,delimiter='\\t'); cols=next(r)[3:]; m=len(cols); total=[0]*m
    top={i:[] for i in range(m)}
    for row in r:
        n+=1
        vals=list(map(int,row[3:])); chrom,start,end=row[0],row[1],row[2]
        s=sum(vals)
        for i,v in enumerate(vals):
            total[i]+=v
            if s>0:
                ratio=v/s
                heapq.heappush(top[i],(ratio,v,chrom,start,end,s))
                if len(top[i])>10: heapq.heappop(top[i])
for i in range(m):
    print('\\n',cols[i], 'total', total[i])
    for ratio,v,c,s,e,allv in sorted(top[i], reverse=True):
        print(f'{c}:{s}-{e} val={v} sum={allv} ratio={ratio:.3f}')
PY"

